class Branch {
  int compute(boolean flag) {
    if (flag) {
      return 1;
    }
    return 2;
  }
}

class Join {
  int compute(boolean flag) {
    int x;
    if (flag) {
      x = 1;
    } else {
      x = 2;
    }
    return x;
  }
}

class Early {
  int compute(boolean stop) {
    int x = 1;
    if (stop) {
      x = 2;
      return x;
    }
    return x;
  }
}

class Repeat {
  int compute(int n) {
    while (n > 0) {
      n--;
    }
    return 0;
  }
}

class Unsupported {
  int compute(int n) {
    try { return n; } finally { n++; }
  }
}

class Old {
  int compute(int n) {
    return n;
  }
}

class NoEvidence {
  int compute(int n) {
    return n;
  }
}
